// Chapter 7, batch 2 (the lift, the hatch and the roof) cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch7, boards 03 and 04).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['c7-climb', ["The lift creaks up through every floor"]],
    ['c7-hatch', ["Beside the empty throne, Kagemaru is waiting with his stall", "I was here, you know. 1984", "I can show you the hatch", "Love?", "You were winning, my lady", "They pay. Kai puts down", "Dutch keeps his hand on Lina", "Mira puts the list down last", "He shows them the hatch.", "The one thing each of you kept"]],
    ['c7-hatch-vault', ["The empty throne, and beside it a speaker", "I was here, you know. 1984", "I can show you the hatch", "Love?", "You were winning, my lady", "They pay. Kai puts down", "Dutch keeps his hand on Lina", "Mira puts the list down last", "He shows them the hatch.", "The one thing each of you kept"]],
    ['c7-wake', ["bruised. The climb will start again"]],
    ['c7-roof', ["The tower's roof is the top of the Cloud", "Dutch finds it the way he has found everything"]],
    ['c7-console', ["The Cloud is a member account in an organization", "In its policy list is one service control policy"]],
    ['c7-blackout', ["Kai attaches it as Gary left it"]],
    ['c7-dark', ["Far below, every light in the camp goes out", "Undo! Undo!", "Detach it."]],
    ['c7-roles', ["Her copies in every role go still", "She's not in the roles"]],
    ['c7-mgmt', ["They attach it to the console's own account", "House rules never reach the head account"]],
    ['c7-attach', ["deny everything, when the principal is the Cloud's root user", "Freya is still root", "Uptima, far below at the fire, signs in"]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
